:root {
    color-scheme: light;
    --paper: #f8f5ef;
    --card: #fffdf9;
    --ink: #292724;
    --muted: #77716b;
    --line: #dfd8ce;
    --accent: #b9583f;
    --accent-deep: #8e3f2f;
    --sidebar: #302d29;
    font-family: Inter, ui-sans-serif, system-ui, sans-serif;
}

* { box-sizing: border-box; }
body { margin: 0; min-width: 320px; background: var(--paper); color: var(--ink); }
button, input, select, textarea { font: inherit; }
button, input, select, textarea, .mood { transition: border-color 160ms ease, box-shadow 160ms ease, transform 160ms ease; }
.shell { display: grid; grid-template-columns: minmax(290px, 32vw) minmax(0, 1fr); min-height: 100vh; }

.sidebar { position: sticky; top: 0; display: flex; flex-direction: column; min-height: 100vh; padding: 48px clamp(32px, 4vw, 72px); overflow: hidden; background: var(--sidebar); color: #f9f3e9; }
.sidebar::after { position: absolute; right: -120px; bottom: -160px; width: 360px; height: 360px; border: 1px solid #ffffff1c; border-radius: 50%; box-shadow: 0 0 0 64px #ffffff0b, 0 0 0 128px #ffffff08; content: ""; }
.brand { z-index: 1; display: inline-flex; align-items: center; gap: 10px; width: fit-content; color: inherit; font-weight: 700; text-decoration: none; }
.brand-mark { display: grid; width: 34px; height: 34px; place-items: center; border-radius: 50% 50% 50% 16%; background: var(--accent); color: white; font-family: "Iowan Old Style", Baskerville, Georgia, serif; font-size: 19px; }
.sidebar-copy { z-index: 1; max-width: 390px; margin: clamp(64px, 11vh, 118px) 0 54px; }
.eyebrow { margin: 0 0 12px; color: var(--accent); font-size: 12px; font-weight: 700; letter-spacing: .13em; text-transform: uppercase; }
.sidebar .eyebrow { color: #e6a18f; }
.sidebar h1 { margin: 0 0 20px; font-family: "Iowan Old Style", Baskerville, Georgia, serif; font-size: clamp(36px, 4vw, 56px); font-weight: 600; letter-spacing: -.035em; line-height: 1.04; }
.sidebar-copy > p:last-child { margin: 0; color: #c9c2b9; line-height: 1.65; }
.steps { z-index: 1; display: grid; gap: 0; margin: 0; padding: 0; list-style: none; }
.step { position: relative; display: grid; grid-template-columns: 34px 1fr; gap: 14px; min-height: 72px; color: #827d77; }
.step::after { position: absolute; top: 34px; bottom: 0; left: 16px; width: 1px; background: #ffffff1c; content: ""; }
.step:last-child::after { display: none; }
.step-dot { z-index: 1; display: grid; width: 34px; height: 34px; place-items: center; border: 1px solid #5b5751; border-radius: 50%; background: var(--sidebar); font-size: 13px; }
.step strong, .step small { display: block; }
.step strong { margin: 1px 0 4px; font-size: 14px; }
.step small { font-size: 12px; }
.step.is-current { color: #fff9f0; }
.step.is-current .step-dot { border-color: var(--accent); background: var(--accent); }
.step.is-complete { color: #bdb7af; }
.step.is-complete .step-dot { border-color: #77716a; color: #f7d6cc; }
.privacy { z-index: 1; margin: auto 0 0; color: #827d77; font-size: 11px; }

.content { display: flex; flex-direction: column; min-width: 0; padding: 46px clamp(24px, 7vw, 112px) 26px; }
.mobile-header, .progress-track { display: none; }
.form-card { width: min(720px, 100%); margin: auto; }
.panel { animation: reveal 240ms ease both; }
@keyframes reveal { from { opacity: 0; transform: translateY(8px); } }
.panel h2, .success h2 { margin: 0 0 14px; font-family: "Iowan Old Style", Baskerville, Georgia, serif; font-size: clamp(34px, 4.1vw, 50px); font-weight: 600; letter-spacing: -.03em; line-height: 1.08; }
.lede { max-width: 590px; margin: 0 0 40px; color: var(--muted); font-size: 16px; line-height: 1.65; }
.field { display: grid; gap: 8px; margin-bottom: 28px; }
.field > span, legend { font-size: 14px; font-weight: 600; }
.field small { color: var(--muted); font-size: 12px; }
input, select, textarea { width: 100%; border: 1px solid var(--line); border-radius: 11px; outline: none; background: var(--card); color: var(--ink); }
input, select { height: 52px; padding: 0 15px; }
textarea { min-height: 132px; padding: 14px 15px; resize: vertical; }
input:focus, select:focus, textarea:focus { border-color: var(--accent); box-shadow: 0 0 0 4px #b9583f18; }
input[aria-invalid="true"], select[aria-invalid="true"], textarea[aria-invalid="true"] { border-color: #b3261e; box-shadow: 0 0 0 3px #b3261e14; }
.field-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 20px; }
.choice-field { margin: 36px 0 0; padding: 0; border: 0; }
.choice-field legend { margin-bottom: 14px; }
.mood-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 12px; }
.mood { position: relative; display: grid; gap: 13px; padding: 10px; border: 1px solid var(--line); border-radius: 14px; background: var(--card); cursor: pointer; }
.mood > input, .swatches input { position: absolute; width: 1px; height: 1px; opacity: 0; }
.mood:has(input:checked) { border-color: var(--accent); box-shadow: 0 0 0 2px #b9583f1c; }
.mood:has(input:focus-visible), .swatches label:has(input:focus-visible) { outline: 2px solid var(--accent); outline-offset: 3px; }
.mood-art { position: relative; display: block; height: 92px; overflow: hidden; border-radius: 9px; background: #e6d3bd; }
.mood-art::before { position: absolute; right: 12%; bottom: -18px; left: 12%; height: 65px; border-radius: 50% 50% 0 0; background: #f8e8d4; content: ""; }
.mood-art i { position: absolute; z-index: 1; border-radius: 50%; background: #5a493e; }
.mood-art i:first-child { right: 24%; bottom: 18px; width: 25px; height: 25px; }
.mood-art i:last-child { bottom: 12px; left: 28%; width: 34px; height: 10px; border-radius: 50%; }
.mood-art.bright { background: #dce6d2; }
.mood-art.bright::before { background: #fff9e6; transform: rotate(-6deg); }
.mood-art.bright i { background: #82996e; }
.mood-art.bold { background: #d9d4cf; }
.mood-art.bold::before { right: -8px; bottom: -28px; left: 32%; height: 100px; border-radius: 12px 0 0; background: #373a3e; transform: rotate(-5deg); }
.mood-art.bold i { background: #d85e3f; }
.mood strong, .mood small { display: block; }
.mood strong { margin-bottom: 3px; font-size: 13px; }
.mood small { color: var(--muted); font-size: 11px; }
.compact { margin-top: 26px; }
.swatches { display: flex; gap: 13px; }
.swatches label { display: block; border-radius: 50%; cursor: pointer; }
.swatches span { display: block; width: 32px; height: 32px; border: 4px solid var(--paper); border-radius: 50%; background: var(--swatch); box-shadow: 0 0 0 1px var(--line); }
.swatches label:has(input:checked) span { box-shadow: 0 0 0 2px var(--paper), 0 0 0 4px var(--swatch); }
.checks { display: flex; flex-wrap: wrap; gap: 10px; }
.checks label { cursor: pointer; }
.checks input { position: absolute; width: 1px; opacity: 0; }
.checks span { display: block; padding: 10px 15px; border: 1px solid var(--line); border-radius: 100px; background: var(--card); font-size: 13px; }
.checks label:has(input:checked) span { border-color: var(--accent); background: #b9583f0c; color: var(--accent-deep); }
.consent { display: flex; align-items: flex-start; gap: 11px; color: var(--muted); font-size: 13px; line-height: 1.5; }
.consent input { width: 18px; height: 18px; margin: 1px 0 0; accent-color: var(--accent); }
.actions { display: grid; grid-template-columns: 1fr auto 1fr; align-items: center; gap: 18px; margin-top: 44px; padding-top: 24px; border-top: 1px solid var(--line); }
.actions button, .success button { min-height: 46px; padding: 0 20px; border-radius: 10px; cursor: pointer; font-weight: 600; }
.back { justify-self: start; border: 0; background: transparent; color: var(--muted); }
.back:disabled { visibility: hidden; }
.next, .success button { justify-self: end; border: 1px solid var(--accent); background: var(--accent); color: white; box-shadow: 0 8px 24px #b9583f22; }
.next:hover, .success button:hover { border-color: var(--accent-deep); background: var(--accent-deep); transform: translateY(-1px); }
.autosave { display: flex; align-items: center; gap: 7px; color: #8d8881; font-size: 11px; }
.autosave i { width: 6px; height: 6px; border-radius: 50%; background: #82996e; }
.success { max-width: 600px; padding: 40px 0; animation: reveal 240ms ease both; }
.success-mark { display: grid; width: 56px; height: 56px; margin-bottom: 28px; place-items: center; border-radius: 50%; background: #e1eadb; color: #536d49; font-size: 22px; }
.success > p:not(.eyebrow) { margin: 0 0 28px; color: var(--muted); line-height: 1.65; }
.success button { justify-self: auto; }
.mockup-note { margin: auto auto 0; padding-top: 36px; color: #a39d95; font-size: 10px; letter-spacing: .04em; }

@media (max-width: 840px) {
    .shell { display: block; }
    .sidebar { display: none; }
    .content { min-height: 100vh; padding: 0 22px 24px; }
    .mobile-header { display: flex; align-items: center; justify-content: space-between; padding: 19px 0; }
    .mobile-header .brand { color: var(--ink); }
    .mobile-progress { color: var(--muted); font-size: 12px; font-weight: 600; }
    .progress-track { display: block; height: 3px; margin: 0 -22px 48px; background: #e8e1d8; }
    .progress-track span { display: block; width: 50%; height: 100%; background: var(--accent); transition: width 220ms ease; }
    .form-card { margin: 0 auto; }
}

@media (max-width: 590px) {
    .content { padding-inline: 18px; }
    .progress-track { margin-inline: -18px; margin-bottom: 36px; }
    .panel h2, .success h2 { font-size: 34px; }
    .lede { margin-bottom: 30px; font-size: 14px; }
    .field-grid, .mood-grid { grid-template-columns: 1fr; }
    .mood { grid-template-columns: 110px 1fr; align-items: center; }
    .mood-art { height: 76px; }
    .actions { grid-template-columns: auto 1fr; }
    .autosave { display: none; }
    .next { justify-self: end; }
}

@media (prefers-reduced-motion: reduce) {
    *, *::before, *::after { scroll-behavior: auto !important; transition: none !important; animation: none !important; }
}

