import { Editor, registerEditor, type SettingSection } from "@bernouy/cms-content/editor";

export class FormsRendererEditor extends Editor {
    protected override settings(): SettingSection[] {
        return [
            {
                kind: "self",
                label: "Form",
                settings: [
                    { type: "text", label: "Form key", attribute: "form-key" },
                    {
                        type: "segmented",
                        label: "Access",
                        attribute: "access",
                        defaultValue: "public",
                        options: [
                            { label: "Public", value: "public" },
                            { label: "Signed in", value: "authenticated" },
                        ],
                    },
                    { type: "text", label: "Exact version (optional)", attribute: "version" },
                ],
            },
            {
                kind: "self",
                label: "Data",
                settings: [
                    { type: "text", label: "Forms source", attribute: "source-id", defaultValue: "forms" },
                    {
                        type: "text",
                        label: "Source prefix",
                        attribute: "source-prefix",
                        defaultValue: "/.cms/sources",
                    },
                ],
            },
        ];
    }
}

registerEditor({ editor: FormsRendererEditor });

blocs/form-renderer/definition.ts.content:
export const fieldTypes = [
    "text",
    "email",
    "tel",
    "number",
    "date",
    "textarea",
    "select",
    "choice",
    "checkbox",
] as const;
export type FieldType = (typeof fieldTypes)[number];

export interface FormOption {
    label: string;
    key?: string;
    value?: string;
    image?: {
        mediaId: string;
        alt?: string;
    };
    imageUrl?: string;
    imageAlt?: string;
}

export interface FormField {
    key: string;
    type: FieldType;
    label: string;
    hint?: string;
    placeholder?: string;
    required?: boolean;
    autocomplete?: string;
    multiple?: boolean;
    presentation?: "image-grid";
    options?: FormOption[];
}

export interface FormStep {
    id: string;
    title: string;
    description?: string;
    fields: FormField[];
}

export interface FormDefinition {
    schemaVersion: 1;
    title: string;
    description?: string;
    submitLabel?: string;
    successMessage?: string;
    minCompletionMs?: number;
    steps: FormStep[];
}

export interface PublishedForm {
    key: string;
    version: number;
    accessMode: "public" | "authenticated";
    definition: FormDefinition;
}

export type FormAnswers = Record<string, string | string[]>;

function isRecord(value: unknown): value is Record<string, unknown> {
    return typeof value === "object" && value !== null && !Array.isArray(value);
}

export function parsePublishedForm(value: unknown): PublishedForm {
    if (!isRecord(value) || !isRecord(value.definition)) {
        throw new Error("The Forms Source returned an invalid form.");
    }
    const definition = value.definition;
    const steps = definition.steps;
    if (
        definition.schemaVersion !== 1 ||
        typeof definition.title !== "string" ||
        !Array.isArray(steps) ||
        steps.length === 0
    ) {
        throw new Error("This form definition is not supported.");
    }
    for (const step of steps) {
        assertStep(step);
    }
    if (typeof value.key !== "string" || !Number.isSafeInteger(value.version)) {
        throw new Error("The published form has no stable identity.");
    }
    return value as unknown as PublishedForm;
}

function assertStep(value: unknown): asserts value is FormStep {
    if (
        !isRecord(value) ||
        typeof value.id !== "string" ||
        typeof value.title !== "string" ||
        !Array.isArray(value.fields)
    ) {
        throw new Error("A form step is invalid.");
    }
    for (const field of value.fields) {
        assertField(field);
    }
}

function assertField(field: unknown): asserts field is FormField {
    if (
        !isRecord(field) ||
        typeof field.key !== "string" ||
        typeof field.label !== "string" ||
        !fieldTypes.includes(field.type as FieldType)
    ) {
        throw new Error("A form field is invalid.");
    }
    if (field.type !== "select" && field.type !== "choice") {
        return;
    }
    if (!Array.isArray(field.options) || field.options.length === 0) {
        throw new Error("A choice field has no options.");
    }
    for (const option of field.options) {
        if (!isRecord(option) || typeof option.label !== "string" || !optionKey(option as FormOption)) {
            throw new Error("A form option is invalid.");
        }
        if (field.presentation === "image-grid" && !validImageOption(option as FormOption)) {
            throw new Error("An image choice has an invalid image.");
        }
    }
    if (field.presentation !== undefined && (field.type !== "choice" || field.presentation !== "image-grid")) {
        throw new Error("A choice presentation is invalid.");
    }
}

export function optionKey(option: FormOption): string {
    const key = String(option.key ?? option.value ?? "").trim();
    return /^[a-z][A-Za-z0-9_-]*$/.test(key) && key.length <= 80 ? key : "";
}

export function safeImageSource(value: unknown): string {
    if (typeof value !== "string" || !value || value.length > 2048) {
        return "";
    }
    if (value.startsWith("/") && !value.startsWith("//")) {
        return value;
    }
    try {
        return new URL(value).protocol === "https:" ? value : "";
    } catch {
        return "";
    }
}

function validImageOption(option: FormOption): boolean {
    if (option.image && typeof option.image.mediaId === "string" && /^[1-9][0-9]{0,18}$/.test(option.image.mediaId)) {
        return (
            option.image.alt === undefined || (typeof option.image.alt === "string" && option.image.alt.length <= 240)
        );
    }
    return Boolean(safeImageSource(option.imageUrl));
}

