import { HttpError } from "./http.ts";

function requiredEnv(name: string): string {
    const value = Deno.env.get(name)?.trim();
    if (!value) {
        throw new HttpError(500, `${name} is not configured`);
    }
    return value;
}

export function requireCmsRequest(request: Request): void {
    const authorization = request.headers.get("authorization") ?? "";
    const token = authorization.startsWith("Bearer ") ? authorization.slice(7).trim() : "";
    if (!token || !safeEqual(token, requiredEnv("CMS_FORMS_API_KEY"))) {
        throw new HttpError(401, "invalid CMS API key");
    }
}

export function cmsUserId(request: Request): string {
    const value = request.headers.get("x-cms-user-id")?.trim() || "";
    if (!value || value.length > 200) {
        throw new HttpError(401, "trusted CMS user id is required");
    }
    return value;
}

export function requireCmsAdmin(request: Request): string {
    if (request.headers.get("x-cms-user-role")?.trim() !== "admin") {
        throw new HttpError(403, "CMS admin role is required");
    }
    return cmsUserId(request);
}

export function serviceRoleKey(): string {
    return requiredEnv("SUPABASE_SERVICE_ROLE_KEY");
}

export function supabaseUrl(): string {
    return requiredEnv("SUPABASE_URL").replace(/\/+$/, "");
}

function safeEqual(left: string, right: string): boolean {
    if (left.length !== right.length) {
        return false;
    }
    let result = 0;
    for (let index = 0; index < left.length; index++) {
        result |= left.charCodeAt(index) ^ right.charCodeAt(index);
    }
    return result === 0;
}

import { HttpError, isRecord } from "../http.ts";
import { rpcRecord } from "../rest.ts";
import { formDefinition } from "../validation.ts";
import { builderReference, type BuilderReference } from "./references.ts";

export type FormQuestion = Record<string, unknown> & {
    key: string;
    label: string;
    type: string;
};

export type FormSection = Record<string, unknown> & {
    id: string;
    title: string;
    fields: FormQuestion[];
};

export type EditableDefinition = Record<string, unknown> & {
    schemaVersion: 1;
    title: string;
    steps: FormSection[];
};

export type EditableForm = {
    reference: BuilderReference;
    managed: Record<string, unknown>;
    definition: EditableDefinition;
};

export async function editableForm(context: unknown): Promise<EditableForm> {
    const reference = builderReference(context);
    const managed = await rpcRecord("get_managed_form", { p_form_key: reference.formKey });
    const definition = structuredClone(formDefinition(managed.draftDefinition)) as EditableDefinition;
    return { reference, managed, definition };
}

export async function saveEditableForm(
    form: EditableForm,
    definition: EditableDefinition,
    actor: string,
): Promise<Record<string, unknown>> {
    definition.title = requiredText(form.managed.title, "form title", 240);
    const valid = formDefinition(definition);
    return await rpcRecord("save_form_draft", {
        p_form_key: form.reference.formKey,
        p_title: form.managed.title,
        p_description: form.managed.description ?? null,
        p_access_mode: form.managed.accessMode,
        p_definition: valid,
        p_actor_id: actor,
    });
}

export function starterDefinition(title: unknown): EditableDefinition {
    const formTitle = String(title ?? "Untitled form").trim() || "Untitled form";
    return {
        schemaVersion: 1,
        title: formTitle,
        successMessage: "Your answers have been received.",
        steps: [
            {
                id: "details",
                title: "First section",
                description: "Start by adapting this section to your form.",
                fields: [{ key: "name", label: "Name", type: "text", required: true }],
            },
        ],
    };
}

export function sectionIn(form: EditableForm): FormSection {
    const section = form.definition.steps.find((candidate) => candidate.id === form.reference.sectionId);
    if (!section) {
        throw new HttpError(404, "section does not exist");
    }
    return section;
}

export function questionIn(form: EditableForm): { section: FormSection; question: FormQuestion } {
    const section = sectionIn(form);
    const question = section.fields.find((candidate) => candidate.key === form.reference.questionKey);
    if (!question) {
        throw new HttpError(404, "question does not exist");
    }
    return { section, question };
}

export function requiredText(value: unknown, name: string, maximum = 240): string {
    const result = String(value ?? "").trim();
    if (!result || result.length > maximum) {
        throw new HttpError(422, `${name} is required and must be at most ${maximum} characters`);
    }
    return result;
}

export function optionalText(value: unknown, maximum = 4000): string | undefined {
    const result = String(value ?? "").trim();
    if (result.length > maximum) {
        throw new HttpError(422, `text must be at most ${maximum} characters`);
    }
    return result || undefined;
}

export function stringArray(value: unknown, name: string): string[] {
    if (!Array.isArray(value) || value.some((item) => typeof item !== "string")) {
        throw new HttpError(422, `${name} must be an array of identifiers`);
    }
    return value;
}

export function recordArray(value: unknown): Record<string, unknown>[] {
    if (!Array.isArray(value) || !value.every(isRecord)) {
        throw new HttpError(422, "options must be an array");
    }
    return value;
}

import { HttpError, isRecord } from "../http.ts";
import { optionalText, recordArray, requiredText } from "./model.ts";

export function normalizedOptions(value: unknown, imagesRequired: boolean): Record<string, unknown>[] {
    const keys = new Set<string>();
    const options = recordArray(value).map((option) => {
        const key = optionKey(option, true);
        if (keys.has(key)) {
            throw new HttpError(422, `option key "${key}" is duplicated`);
        }
        keys.add(key);
        const image = normalizedImage(option, imagesRequired);
        return {
            key,
            label: requiredText(option.label, "option label", 160),
            ...image,
        };
    });
    if (options.length === 0) {
        throw new HttpError(422, "a choice question needs at least one option");
    }
    return options;
}

export function optionItems(value: unknown): Record<string, unknown>[] {
    if (!Array.isArray(value)) {
        return [];
    }
    return value.filter(isRecord).map((option, index) => {
        const key = optionKey(option, false) || `option-${index + 1}`;
        const legacyUrl = normalizedImageUrl(option.imageUrl, false);
        const legacyAlt = optionalText(option.imageAlt, 240);
        const image = isRecord(option.image)
            ? option.image
            : legacyUrl
              ? { url: legacyUrl, ...(legacyAlt ? { alt: legacyAlt } : {}) }
              : undefined;
        return { ...option, ...(image ? { image } : {}), key, id: key, position: index };
    });
}

export function optionKey(option: Record<string, unknown>, required: boolean): string {
    const key = String(option.key ?? option.value ?? "").trim();
    if (!key && !required) {
        return "";
    }
    if (!key || key.length > 80 || !/^[a-z][A-Za-z0-9_-]*$/.test(key)) {
        throw new HttpError(422, "option keys must start with a letter and use only letters, numbers, _ or -");
    }
    return key;
}

export function normalizedQuestionKey(value: unknown): string {
    const key = requiredText(value, "question key", 80);
    if (!/^[a-z][A-Za-z0-9_]*$/.test(key)) {
        throw new HttpError(422, "question keys must start with a lowercase letter and use letters, numbers or _");
    }
    return key;
}

function normalizedImageUrl(value: unknown, required: boolean): string | undefined {
    const imageUrl = optionalText(value, 2048);
    if (!imageUrl) {
        if (required) {
            throw new HttpError(422, "every image choice needs an image");
        }
        return undefined;
    }
    if (imageUrl.startsWith("/") && !imageUrl.startsWith("//")) {
        return imageUrl;
    }
    try {
        if (new URL(imageUrl).protocol === "https:") {
            return imageUrl;
        }
    } catch {
        // Report the same bounded validation error below.
    }
    throw new HttpError(422, "image URLs must use HTTPS or a CMS-relative /path");
}

function normalizedImage(option: Record<string, unknown>, required: boolean): Record<string, unknown> {
    const value = isRecord(option.image) ? option.image : {};
    const rawId = value.mediaId ?? value.id;
    const mediaId = String(rawId ?? "").trim();
    const alt = optionalText(value.alt ?? option.imageAlt, 240);
    if (/^[1-9][0-9]{0,18}$/.test(mediaId)) {
        return { image: { mediaId, ...(alt ? { alt } : {}) } };
    }
    const imageUrl = normalizedImageUrl(value.url ?? option.imageUrl, required);
    return imageUrl ? { imageUrl, ...(alt ? { imageAlt: alt } : {}) } : {};
}

import { HttpError } from "../http.ts";
import {
    editableForm,
    optionalText,
    questionIn,
    requiredText,
    saveEditableForm,
    sectionIn,
    stringArray,
    type EditableForm,
    type FormQuestion,
    type FormSection,
} from "./model.ts";
import { normalizedOptions, normalizedQuestionKey, optionItems } from "./options.ts";
import { builderReference, questionReference, sectionReference } from "./references.ts";

const choiceTypes = new Set(["select", "choice"]);
const questionTypes = new Set(["text", "email", "tel", "number", "date", "textarea", "select", "choice", "checkbox"]);

export async function listQuestions(context: unknown): Promise<Record<string, unknown>> {
    const form = await editableForm(context);
    const section = sectionIn(form);
    return { items: section.fields.map((question, index) => questionItem(form, section, question, index)) };
}

export async function getQuestion(reference: unknown): Promise<Record<string, unknown>> {
    const form = await editableForm(reference);
    const { section, question } = questionIn(form);
    return questionDetail(form, section, question);
}

export async function createQuestion(context: unknown, actor: string): Promise<Record<string, unknown>> {
    const form = await editableForm(context);
    const section = sectionIn(form);
    const count = form.definition.steps.reduce((total, candidate) => total + candidate.fields.length, 0);
    if (count >= 100) {
        throw new HttpError(422, "a form cannot contain more than 100 questions");
    }
    const question: FormQuestion = {
        key: uniqueQuestionKey(form),
        label: "Untitled question",
        type: "text",
        required: false,
    };
    section.fields.push(question);
    await saveEditableForm(form, form.definition, actor);
    return questionDetail(form, section, question);
}

export async function saveQuestion(input: Record<string, unknown>, actor: string): Promise<Record<string, unknown>> {
    const form = await editableForm(input.ref);
    const { section, question } = questionIn(form);
    const type = String(input.type ?? "");
    if (!questionTypes.has(type)) {
        throw new HttpError(422, "question type is not supported");
    }
    const key = normalizedQuestionKey(input.key);
    if (
        key !== question.key &&
        form.definition.steps.some((candidate) => candidate.fields.some((field) => field.key === key))
    ) {
        throw new HttpError(422, `question key "${key}" is already used`);
    }
    question.key = key;
    question.label = requiredText(input.label, "question label", 240);
    question.type = type;
    setOptional(question, "hint", input.hint);
    setOptional(question, "placeholder", input.placeholder, 240);
    question.required = input.required === true;
    if (choiceTypes.has(type)) {
        const imageGrid = type === "choice" && input.presentation === "image-grid";
        const optionInput = imageGrid ? (input.imageOptions ?? input.options) : input.options;
        question.options = normalizedOptions(optionInput, imageGrid);
        question.multiple = type === "choice" && input.multiple === true;
        if (imageGrid) {
            question.presentation = "image-grid";
        } else {
            delete question.presentation;
        }
    } else {
        delete question.options;
        delete question.multiple;
        delete question.presentation;
    }
    await saveEditableForm(form, form.definition, actor);
    return questionDetail(form, section, question);
}

export async function deleteQuestion(reference: unknown, actor: string): Promise<Record<string, unknown>> {
    const form = await editableForm(reference);
    const { section, question } = questionIn(form);
    const count = form.definition.steps.reduce((total, candidate) => total + candidate.fields.length, 0);
    if (count === 1) {
        throw new HttpError(422, "keep at least one question in the form");
    }
    section.fields = section.fields.filter((candidate) => candidate.key !== question.key);
    await saveEditableForm(form, form.definition, actor);
    return { ok: true, sectionRef: sectionReference(form.reference.formKey, section.id) };
}

export async function reorderQuestions(
    context: unknown,
    value: unknown,
    actor: string,
): Promise<Record<string, unknown>> {
    const form = await editableForm(context);
    const section = sectionIn(form);
    const references = stringArray(value, "question order");
    const keys = references.map((reference) => builderReference(reference).questionKey);
    const expected = new Set(section.fields.map((question) => question.key));
    if (keys.length !== expected.size || keys.some((key) => !key || !expected.delete(key))) {
        throw new HttpError(422, "question order must contain every question exactly once");
    }
    const byKey = new Map(section.fields.map((question) => [question.key, question]));
    section.fields = keys.map((key) => byKey.get(key!)!);
    await saveEditableForm(form, form.definition, actor);
    return await listQuestions(sectionReference(form.reference.formKey, section.id));
}

function questionItem(
    form: EditableForm,
    section: FormSection,
    question: FormQuestion,
    position: number,
): Record<string, unknown> {
    return {
        id: questionReference(form.reference.formKey, section.id, question.key),
        key: question.key,
        title: question.label,
        subtitle: question.required === true ? "Required" : "Optional",
        badge: question.type,
        position,
    };
}

function questionDetail(form: EditableForm, section: FormSection, question: FormQuestion): Record<string, unknown> {
    const options = optionItems(question.options);
    return {
        ...questionItem(form, section, question, section.fields.indexOf(question)),
        ref: questionReference(form.reference.formKey, section.id, question.key),
        sectionRef: sectionReference(form.reference.formKey, section.id),
        formKey: form.reference.formKey,
        sectionTitle: section.title,
        label: question.label,
        type: question.type,
        required: question.required === true,
        hint: question.hint ?? "",
        placeholder: question.placeholder ?? "",
        multiple: question.multiple === true,
        presentation: question.presentation === "image-grid" ? "image-grid" : "chips",
        options,
    };
}

function setOptional(target: Record<string, unknown>, key: string, value: unknown, maximum = 1000): void {
    const result = optionalText(value, maximum);
    if (result) {
        target[key] = result;
    } else {
        delete target[key];
    }
}

function uniqueQuestionKey(form: EditableForm): string {
    const used = new Set(form.definition.steps.flatMap((section) => section.fields.map((question) => question.key)));
    for (let index = used.size + 1; index <= 200; index++) {
        const candidate = `question${index}`;
        if (!used.has(candidate)) {
            return candidate;
        }
    }
    return `question_${crypto.randomUUID().replaceAll("-", "").slice(0, 12)}`;
}

import { HttpError, isRecord } from "../http.ts";

export type BuilderReference = {
    formKey: string;
    sectionId?: string;
    questionKey?: string;
};

const formKeyPattern = /^[a-z0-9]+(?:-[a-z0-9]+)*$/;

export function builderReference(value: unknown): BuilderReference {
    const raw = String(value ?? "").trim();
    if (formKeyPattern.test(raw)) {
        return { formKey: raw };
    }
    try {
        const decoded = JSON.parse(atob(fromBase64Url(raw)));
        if (!isRecord(decoded) || !formKeyPattern.test(String(decoded.formKey ?? ""))) {
            throw new Error("invalid form key");
        }
        const result: BuilderReference = { formKey: String(decoded.formKey) };
        if (text(decoded.sectionId)) {
            result.sectionId = String(decoded.sectionId);
        }
        if (text(decoded.questionKey)) {
            result.questionKey = String(decoded.questionKey);
        }
        return result;
    } catch {
        throw new HttpError(422, "builder context is invalid");
    }
}

export function sectionReference(formKey: string, sectionId: string): string {
    return encode({ formKey, sectionId });
}

export function questionReference(formKey: string, sectionId: string, questionKey: string): string {
    return encode({ formKey, sectionId, questionKey });
}

function encode(value: BuilderReference): string {
    return btoa(JSON.stringify(value)).replaceAll("+", "-").replaceAll("/", "_").replace(/=+$/, "");
}

function fromBase64Url(value: string): string {
    const normalized = value.replaceAll("-", "+").replaceAll("_", "/");
    return normalized.padEnd(Math.ceil(normalized.length / 4) * 4, "=");
}

function text(value: unknown): boolean {
    return typeof value === "string" && value.trim().length > 0 && value.length <= 80;
}

import { HttpError } from "../http.ts";
import {
