    return { items: form.definition.steps.map((section, index) => sectionItem(form, section, index)) };
}

export async function getSection(reference: unknown): Promise<Record<string, unknown>> {
    const form = await editableForm(reference);
    return sectionDetail(form, sectionIn(form));
}

export async function createSection(context: unknown, actor: string): Promise<Record<string, unknown>> {
    const form = await editableForm(context);
    if (form.definition.steps.length >= 20) {
        throw new HttpError(422, "a form cannot contain more than 20 sections");
    }
    const section: FormSection = {
        id: uniqueSectionId(form),
        title: "Untitled section",
        fields: [],
    };
    form.definition.steps.push(section);
    await saveEditableForm(form, form.definition, actor);
    return sectionDetail(form, section);
}

export async function saveSection(input: Record<string, unknown>, actor: string): Promise<Record<string, unknown>> {
    const form = await editableForm(input.ref);
    const section = sectionIn(form);
    section.title = requiredText(input.title, "section title", 240);
    const description = optionalText(input.description);
    if (description) {
        section.description = description;
    } else {
        delete section.description;
    }
    await saveEditableForm(form, form.definition, actor);
    return sectionDetail(form, section);
}

export async function deleteSection(reference: unknown, actor: string): Promise<Record<string, unknown>> {
    const form = await editableForm(reference);
    const section = sectionIn(form);
    const remainingQuestions =
        form.definition.steps.reduce((total, item) => total + item.fields.length, 0) - section.fields.length;
    if (form.definition.steps.length === 1 || remainingQuestions < 1) {
        throw new HttpError(422, "keep at least one section and one question in the form");
    }
    form.definition.steps = form.definition.steps.filter((candidate) => candidate.id !== section.id);
    await saveEditableForm(form, form.definition, actor);
    return { ok: true, formKey: form.reference.formKey };
}

export async function reorderSections(
    context: unknown,
    value: unknown,
    actor: string,
): Promise<Record<string, unknown>> {
    const form = await editableForm(context);
    const references = stringArray(value, "section order");
    const ids = references.map((reference) => builderReference(reference).sectionId);
    const expected = new Set(form.definition.steps.map((section) => section.id));
    if (ids.length !== expected.size || ids.some((id) => !id || !expected.delete(id))) {
        throw new HttpError(422, "section order must contain every section exactly once");
    }
    const byId = new Map(form.definition.steps.map((section) => [section.id, section]));
    form.definition.steps = ids.map((id) => byId.get(id!)!);
    await saveEditableForm(form, form.definition, actor);
    return await listSections(form.reference.formKey);
}

function sectionItem(form: EditableForm, section: FormSection, position: number): Record<string, unknown> {
    return {
        id: sectionReference(form.reference.formKey, section.id),
        sectionId: section.id,
        title: section.title,
        subtitle: optionalText(section.description) ?? "No description",
        badge: `${section.fields.length} question${section.fields.length === 1 ? "" : "s"}`,
        position,
    };
}

function sectionDetail(form: EditableForm, section: FormSection): Record<string, unknown> {
    return {
        ...sectionItem(form, section, form.definition.steps.indexOf(section)),
        ref: sectionReference(form.reference.formKey, section.id),
        formKey: form.reference.formKey,
        description: section.description ?? "",
        questionCount: section.fields.length,
    };
}

function uniqueSectionId(form: EditableForm): string {
    const used = new Set(form.definition.steps.map((section) => section.id));
    for (let index = form.definition.steps.length + 1; index <= 100; index++) {
        const candidate = `section_${index}`;
        if (!used.has(candidate)) {
            return candidate;
        }
    }
    return `section_${crypto.randomUUID().replaceAll("-", "").slice(0, 12)}`;
}

import { requireCmsRequest } from "./auth.ts";
import { handleError, json, optionsResponse } from "./http.ts";
import { handleAdminRoute } from "./routes/admin.ts";
import { handleBuilderRoute } from "./routes/builder.ts";
import { handleMediaRoute } from "./routes/media/index.ts";
import { handleSubmissionRoute } from "./routes/submissions.ts";
import { handleSystemRoute } from "./routes/system.ts";
import { handleVisitorRoute } from "./routes/visitor.ts";

const handlers = [
    handleMediaRoute,
    handleVisitorRoute,
    handleBuilderRoute,
    handleSubmissionRoute,
    handleAdminRoute,
    handleSystemRoute,
];

export async function handleFormsRequest(request: Request): Promise<Response> {
    try {
        if (request.method === "OPTIONS") {
            return optionsResponse();
        }
        requireCmsRequest(request);
        const route = routePath(request);
        for (const handler of handlers) {
            const response = await handler(route, request);
            if (response) {
                return response;
            }
        }
        return json({ error: "not found" }, 404);
    } catch (error) {
        return handleError(error);
    }
}

function routePath(request: Request): string {
    const pathname = new URL(request.url).pathname.replace(/\/+$/, "");
    const marker = "/cms-forms";
    const index = pathname.indexOf(marker);
    return index === -1 ? pathname || "/" : pathname.slice(index + marker.length) || "/";
}

export class HttpError extends Error {
    constructor(
        public readonly status: number,
        message: string,
        public readonly fields?: Record<string, string>,
    ) {
        super(message);
    }
}

export const corsHeaders = {
    "access-control-allow-origin": "*",
    "access-control-allow-headers": "authorization, content-type, x-cms-user-id, x-cms-user-role",
    "access-control-allow-methods": "GET, POST, OPTIONS",
};

export function json(value: unknown, status = 200): Response {
    return new Response(JSON.stringify(value), {
        status,
        headers: {
            ...corsHeaders,
            "cache-control": "private, no-store",
            "content-type": "application/json; charset=utf-8",
        },
    });
}

export function optionsResponse(): Response {
    return new Response("ok", { headers: corsHeaders });
}

export function methodNotAllowed(...methods: string[]): Response {
    return new Response("Method Not Allowed", {
        status: 405,
        headers: { ...corsHeaders, allow: [...methods, "OPTIONS"].join(", ") },
    });
}

export function handleError(error: unknown): Response {
    if (error instanceof HttpError) {
        return json({ error: error.message, ...(error.fields ? { fields: error.fields } : {}) }, error.status);
    }
    console.error(error);
    return json({ error: "internal error" }, 500);
}

export function isRecord(value: unknown): value is Record<string, unknown> {
    return typeof value === "object" && value !== null && !Array.isArray(value);
}

export async function requestBody(request: Request): Promise<Record<string, unknown>> {
    const value = await request.json().catch(() => null);
    if (!isRecord(value)) {
        throw new HttpError(400, "request body must be an object");
    }
    return value;
}

export function queryText(url: URL, name: string, required = false): string | null {
    const value = url.searchParams.get(name)?.trim() || null;
    if (required && !value) {
        throw new HttpError(422, `${name} is required`);
    }
    return value;
}

export function boundedInteger(
    value: unknown,
    name: string,
    fallback: number,
    minimum: number,
    maximum: number,
): number {
    const parsed = value === null || value === undefined || value === "" ? fallback : Number(value);
    if (!Number.isSafeInteger(parsed) || parsed < minimum || parsed > maximum) {
        throw new HttpError(422, `${name} must be an integer between ${minimum} and ${maximum}`);
    }
    return parsed;
}

import { serviceRoleKey, supabaseUrl } from "./auth.ts";
import { HttpError, isRecord } from "./http.ts";

const schema = "forms";

export async function rpc(name: string, body: Record<string, unknown> = {}): Promise<unknown> {
    const key = serviceRoleKey();
    const headers = new Headers({
        apikey: key,
        "accept-profile": schema,
        "content-profile": schema,
        "content-type": "application/json",
    });
    if (!key.startsWith("sb_")) {
        headers.set("authorization", `Bearer ${key}`);
    }
    const response = await fetch(`${supabaseUrl()}/rest/v1/rpc/${name}`, {
        method: "POST",
        headers,
        body: JSON.stringify(body),
    });
    if (!response.ok) {
        throw await restError(response);
    }
    return await response.json();
}

export async function rpcRecord(name: string, body: Record<string, unknown> = {}): Promise<Record<string, unknown>> {
    const result = await rpc(name, body);
    if (!isRecord(result)) {
        throw new HttpError(502, `${name} returned an invalid response`);
    }
    return result;
}

async function restError(response: Response): Promise<HttpError> {
    const body = await response.json().catch(() => null);
    const message =
        isRecord(body) && typeof body.message === "string" ? body.message : `Supabase error (${response.status})`;
    const prefix = /^(validation|conflict|forbidden|not_found):\s*/.exec(message)?.[1];
    const clean = message.replace(/^[^:]+:\s*/, "");
    if (prefix === "validation") {
        return new HttpError(422, clean);
    }
    if (prefix === "conflict") {
        return new HttpError(409, clean);
    }
    if (prefix === "forbidden") {
        return new HttpError(403, clean);
    }
    if (prefix === "not_found") {
        return new HttpError(404, clean);
    }
    return new HttpError(response.status < 500 ? 422 : 502, message);
}

import { requireCmsAdmin } from "../auth.ts";
import { boundedInteger, HttpError, json, queryText, requestBody } from "../http.ts";
import { rpcRecord } from "../rest.ts";
import { formDefinition } from "../validation.ts";
