export const formsMediaBucket = "forms-media";
export const maxFormImageBytes = 10 * 1024 * 1024;
export const maxFormImagePixels = 40_000_000;
export const maxMultipartOverheadBytes = 64 * 1024;

import { cmsUserId, requireCmsAdmin } from "../../auth.ts";
import { builderReference } from "../../builder/references.ts";
import { boundedInteger, corsHeaders, HttpError, json, methodNotAllowed, queryText } from "../../http.ts";
import { rpcRecord } from "../../rest.ts";
import { formsMediaBucket } from "./constants.ts";
import { formImagePath, readFormImage } from "./request.ts";
import { deleteStorageImageBestEffort, downloadStorageImage, uploadStorageImage } from "./storage.ts";

export async function handleMediaRoute(route: string, request: Request): Promise<Response | null> {
    if (route === "/admin/form/image") {
        const actor = requireCmsAdmin(request);
        return request.method === "POST" ? await uploadImage(request, actor) : await managedImage(request);
    }
    if (route === "/public/form/image" || route === "/authenticated/form/image") {
        if (request.method !== "GET") {
            return methodNotAllowed("GET");
        }
        const actor = route.startsWith("/authenticated/") ? cmsUserId(request) : null;
        return await publishedImage(request, actor);
    }
    return null;
}

async function uploadImage(request: Request, actor: string): Promise<Response> {
    const reference = builderReference(queryText(new URL(request.url), "ref", true));
    const image = await readFormImage(request);
    const path = formImagePath(reference.formKey, image);
    await uploadStorageImage(formsMediaBucket, path, image.file);
    try {
        const media = await rpcRecord("create_media", {
            p_form_key: reference.formKey,
            p_storage_bucket: formsMediaBucket,
            p_storage_path: path,
            p_mime_type: image.mimeType,
            p_file_size: image.file.size,
            p_width: image.width,
            p_height: image.height,
            p_original_filename: image.file.name,
            p_actor_id: actor,
        });
        return json({ ok: true, ...media });
    } catch (error) {
        await deleteStorageImageBestEffort(formsMediaBucket, path);
        throw error;
    }
}

async function managedImage(request: Request): Promise<Response> {
    if (request.method !== "GET") {
        return methodNotAllowed("GET", "POST");
    }
    const mediaId = positiveQueryInteger(request, "id");
    return await streamImage(await rpcRecord("get_managed_media_context", { p_media_id: mediaId }));
}

async function publishedImage(request: Request, actor: string | null): Promise<Response> {
    const url = new URL(request.url);
    return await streamImage(
        await rpcRecord("get_published_media_context", {
            p_form_key: queryText(url, "key", true),
            p_version: boundedInteger(url.searchParams.get("version"), "version", 0, 1, 2_147_483_647),
            p_media_id: positiveQueryInteger(request, "id"),
            p_actor_id: actor,
        }),
    );
}

async function streamImage(context: Record<string, unknown>): Promise<Response> {
    const bucket = contextText(context, "storageBucket");
    const path = contextText(context, "storagePath");
    const mimeType = contextText(context, "mimeType");
    const stored = await downloadStorageImage(bucket, path);
    const headers = new Headers(corsHeaders);
    headers.set("cache-control", "private, no-store");
    headers.set("content-security-policy", "default-src 'none'");
    headers.set("content-type", mimeType);
    headers.set("x-content-type-options", "nosniff");
    const length = stored.headers.get("content-length");
    if (length) {
        headers.set("content-length", length);
    }
    return new Response(stored.body, { status: 200, headers });
}

function positiveQueryInteger(request: Request, name: string): number {
    const value = boundedInteger(new URL(request.url).searchParams.get(name), name, 0, 1, Number.MAX_SAFE_INTEGER);
    if (!Number.isSafeInteger(value)) {
        throw new HttpError(422, `${name} must be a positive integer`);
    }
    return value;
}

function contextText(context: Record<string, unknown>, name: string): string {
    const value = context[name];
    if (typeof value !== "string" || !value || value.length > 2048) {
        throw new HttpError(502, "media context is invalid");
    }
    return value;
}

import { HttpError } from "../../http.ts";
import { maxMultipartOverheadBytes } from "./constants.ts";
import { parseSingleMultipartFile, type MultipartFile } from "./multipartParser.ts";

export async function readSingleMultipartFile(request: Request, maxFileBytes: number): Promise<MultipartFile> {
    const boundary = multipartBoundary(request.headers.get("content-type"));
    const maxBodyBytes = maxFileBytes + maxMultipartOverheadBytes;
    rejectKnownOversize(request, maxBodyBytes);
    return parseSingleMultipartFile(await readBoundedBody(request, maxBodyBytes), boundary, maxFileBytes);
}

function multipartBoundary(contentType: string | null): string {
    if (!contentType || !/^multipart\/form-data(?:;|$)/i.test(contentType.trim())) {
        throw new HttpError(400, "image upload must use multipart/form-data");
    }
    const match = /;\s*boundary=(?:"([^"]+)"|([^;]+))/i.exec(contentType);
    const boundary = (match?.[1] ?? match?.[2] ?? "").trim();
    if (!boundary || boundary.length > 70 || /[\r\n\x00-\x1f\x7f]/.test(boundary)) {
        throw new HttpError(400, "invalid multipart boundary");
    }
    return boundary;
}

function rejectKnownOversize(request: Request, maximum: number): void {
    const raw = request.headers.get("content-length")?.trim();
    if (raw && /^[0-9]+$/.test(raw) && Number(raw) > maximum) {
        void request.body?.cancel("multipart body exceeds the configured limit").catch(() => undefined);
        throw new HttpError(413, "file is too large");
    }
}

async function readBoundedBody(request: Request, maximum: number): Promise<Uint8Array> {
    if (!request.body) {
        throw new HttpError(400, "invalid multipart body");
    }
    const reader = request.body.getReader();
    const chunks: Uint8Array[] = [];
    let total = 0;
    try {
        for (;;) {
            const result = await reader.read();
            if (result.done) {
                break;
            }
            total += result.value.byteLength;
            if (total > maximum) {
                await reader.cancel("multipart body exceeds the configured limit").catch(() => undefined);
                throw new HttpError(413, "file is too large");
            }
            chunks.push(result.value);
        }
    } finally {
        reader.releaseLock();
    }
    const bytes = new Uint8Array(total);
    let offset = 0;
    for (const chunk of chunks) {
        bytes.set(chunk, offset);
        offset += chunk.byteLength;
    }
    return bytes;
}

import { HttpError } from "../../http.ts";

export type MultipartFile = { bytes: Uint8Array; filename: string };

const decoder = new TextDecoder();
const encoder = new TextEncoder();

export function parseSingleMultipartFile(bytes: Uint8Array, boundary: string, maximum: number): MultipartFile {
    const marker = encoder.encode(`--${boundary}`);
    const delimiter = encoder.encode(`\r\n--${boundary}`);
    if (!matchesAt(bytes, marker, 0)) {
        throw new HttpError(400, "invalid multipart body");
    }
    let cursor = marker.length;
    let file: MultipartFile | null = null;
    for (;;) {
        if (matchesAscii(bytes, "--", cursor)) {
            break;
        }
        if (!matchesAscii(bytes, "\r\n", cursor)) {
            throw new HttpError(400, "invalid multipart body");
        }
        cursor += 2;
        const headerEnd = indexOf(bytes, encoder.encode("\r\n\r\n"), cursor);
        if (headerEnd < 0 || headerEnd - cursor > 16 * 1024) {
            throw new HttpError(400, "invalid multipart headers");
        }
        const disposition = dispositionHeader(decoder.decode(bytes.subarray(cursor, headerEnd)));
        const contentStart = headerEnd + 4;
        const nextBoundary = indexOf(bytes, delimiter, contentStart);
        if (nextBoundary < 0) {
            throw new HttpError(400, "invalid multipart body");
        }
        if (disposition.filename !== null) {
            if (disposition.name !== "file" || file) {
                throw new HttpError(400, "exactly one file is required");
            }
            const contents = bytes.slice(contentStart, nextBoundary);
            if (!contents.byteLength) {
                throw new HttpError(400, "file is empty");
            }
            if (contents.byteLength > maximum) {
                throw new HttpError(413, "file is too large");
            }
            file = { bytes: contents, filename: safeFilename(disposition.filename) };
        }
        cursor = nextBoundary + 2 + marker.length;
    }
    if (!file) {
        throw new HttpError(400, "file is required");
    }
    return file;
}

function dispositionHeader(value: string): { filename: string | null; name: string | null } {
    const line = value.split("\r\n").find((candidate) => /^content-disposition:/i.test(candidate));
    if (!line || !/^content-disposition:\s*form-data(?:;|$)/i.test(line)) {
        throw new HttpError(400, "invalid multipart disposition");
    }
    return { filename: parameter(line, "filename"), name: parameter(line, "name") };
}

function parameter(value: string, name: string): string | null {
    const match = new RegExp(`(?:^|;)\\s*${name}=(?:"((?:[^"\\\\]|\\\\.)*)"|([^;]*))`, "i").exec(value);
    const result = match?.[1] === undefined ? (match?.[2] ?? "").trim() : match[1].replace(/\\(.)/g, "$1");
    if (!match) {
        return null;
    }
    if (/[\r\n\x00]/.test(result)) {
        throw new HttpError(400, "invalid multipart disposition");
    }
    return result;
}

function safeFilename(value: string): string {
    return value.split(/[\\/]/).at(-1)?.trim().slice(0, 500) || "image";
}

function indexOf(haystack: Uint8Array, needle: Uint8Array, start: number): number {
    outer: for (let index = start; index <= haystack.length - needle.length; index++) {
        for (let offset = 0; offset < needle.length; offset++) {
            if (haystack[index + offset] !== needle[offset]) {
                continue outer;
            }
        }
        return index;
    }
    return -1;
}

function matchesAt(bytes: Uint8Array, value: Uint8Array, offset: number): boolean {
    return value.every((byte, index) => bytes[offset + index] === byte);
}

function matchesAscii(bytes: Uint8Array, value: string, offset: number): boolean {
    return matchesAt(bytes, encoder.encode(value), offset);
}

import { HttpError } from "../../../http.ts";

export function ascii(bytes: Uint8Array, offset: number, length: number): string {
    requireBytes(bytes, offset, length);
    return String.fromCharCode(...bytes.subarray(offset, offset + length));
}

export function matches(bytes: Uint8Array, offset: number, expected: readonly number[]): boolean {
    return expected.every((byte, index) => bytes[offset + index] === byte);
}

export function readU16BE(bytes: Uint8Array, offset: number): number {
    requireBytes(bytes, offset, 2);
    return (bytes[offset]! << 8) | bytes[offset + 1]!;
}

export function readU16LE(bytes: Uint8Array, offset: number): number {
    requireBytes(bytes, offset, 2);
    return bytes[offset]! | (bytes[offset + 1]! << 8);
}

export function readU24LE(bytes: Uint8Array, offset: number): number {
    requireBytes(bytes, offset, 3);
    return bytes[offset]! | (bytes[offset + 1]! << 8) | (bytes[offset + 2]! << 16);
}

export function readU32BE(bytes: Uint8Array, offset: number): number {
    requireBytes(bytes, offset, 4);
    return new DataView(bytes.buffer, bytes.byteOffset + offset, 4).getUint32(0, false);
}

export function readU32LE(bytes: Uint8Array, offset: number): number {
    requireBytes(bytes, offset, 4);
    return new DataView(bytes.buffer, bytes.byteOffset + offset, 4).getUint32(0, true);
}

export function requireBytes(bytes: Uint8Array, offset: number, length: number): void {
    if (offset < 0 || length < 0 || offset + length > bytes.length) {
        malformed();
    }
}

export function malformed(): never {
    throw new HttpError(400, "file is not a valid supported image");
}

import { HttpError } from "../../../http.ts";
import { maxFormImagePixels } from "../constants.ts";
import { ascii, malformed, matches, readU16BE, readU16LE, readU24LE, readU32BE, readU32LE } from "./bytes.ts";

export type ProbedImage = {
    extension: string;
    height: number;
    mimeType: string;
    width: number;
};

export function probeFormImage(bytes: Uint8Array): ProbedImage {
    const image = detect(bytes);
    if (!image.width || !image.height || image.width * image.height > maxFormImagePixels) {
        throw new HttpError(400, "image dimensions are invalid or too large");
    }
    return image;
}

function detect(bytes: Uint8Array): ProbedImage {
    if (matches(bytes, 0, [0xff, 0xd8, 0xff])) {
        return { ...jpegDimensions(bytes), extension: ".jpg", mimeType: "image/jpeg" };
    }
    if (matches(bytes, 0, [0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a])) {
        return { width: readU32BE(bytes, 16), height: readU32BE(bytes, 20), extension: ".png", mimeType: "image/png" };
    }
    if (bytes.length >= 10 && ["GIF87a", "GIF89a"].includes(ascii(bytes, 0, 6))) {
        return { width: readU16LE(bytes, 6), height: readU16LE(bytes, 8), extension: ".gif", mimeType: "image/gif" };
    }
    if (bytes.length >= 30 && ascii(bytes, 0, 4) === "RIFF" && ascii(bytes, 8, 4) === "WEBP") {
        return { ...webpDimensions(bytes), extension: ".webp", mimeType: "image/webp" };
    }
    throw new HttpError(400, "file must be a JPEG, PNG, WebP, or GIF image");
}

function jpegDimensions(bytes: Uint8Array): { height: number; width: number } {
    let offset = 2;
    while (offset + 4 < bytes.length) {
        if (bytes[offset++] !== 0xff) {
            malformed();
        }
        while (bytes[offset] === 0xff) {
            offset++;
        }
        const marker = bytes[offset++]!;
        if (marker === 0xd9 || marker === 0xda) {
            break;
        }
        if (marker === 0x01 || (marker >= 0xd0 && marker <= 0xd7)) {
            continue;
        }
        const length = readU16BE(bytes, offset);
        if (length < 2 || offset + length > bytes.length) {
            malformed();
        }
        if ([0xc0, 0xc1, 0xc2, 0xc3, 0xc5, 0xc6, 0xc7, 0xc9, 0xca, 0xcb, 0xcd, 0xce, 0xcf].includes(marker)) {
            return { height: readU16BE(bytes, offset + 3), width: readU16BE(bytes, offset + 5) };
        }
        offset += length;
    }
    malformed();
}

function webpDimensions(bytes: Uint8Array): { height: number; width: number } {
    if (readU32LE(bytes, 4) + 8 !== bytes.length) {
        malformed();
    }
    const kind = ascii(bytes, 12, 4);
    if (kind === "VP8X") {
        return { width: readU24LE(bytes, 24) + 1, height: readU24LE(bytes, 27) + 1 };
    }
    if (kind === "VP8L" && bytes[20] === 0x2f) {
        const bits = readU32LE(bytes, 21);
        return { width: (bits & 0x3fff) + 1, height: ((bits >>> 14) & 0x3fff) + 1 };
    }
    if (kind === "VP8 " && matches(bytes, 23, [0x9d, 0x01, 0x2a])) {
        return { width: readU16LE(bytes, 26) & 0x3fff, height: readU16LE(bytes, 28) & 0x3fff };
    }
    malformed();
}

import { maxFormImageBytes } from "./constants.ts";
import { readSingleMultipartFile } from "./multipart.ts";
import { probeFormImage, type ProbedImage } from "./probe/index.ts";

export type FormImage = ProbedImage & { file: File };

export async function readFormImage(request: Request): Promise<FormImage> {
    const multipart = await readSingleMultipartFile(request, maxFormImageBytes);
    const detected = probeFormImage(multipart.bytes);
    return {
        ...detected,
        file: new File([multipart.bytes], multipart.filename, { type: detected.mimeType }),
    };
}

export function formImagePath(formKey: string, image: FormImage): string {
    const date = new Date().toISOString().slice(0, 10);
    return `forms/${formKey}/${date}/${crypto.randomUUID()}${image.extension}`;
}

import { serviceRoleKey, supabaseUrl } from "../../auth.ts";
import { HttpError, isRecord } from "../../http.ts";

export async function uploadStorageImage(bucket: string, path: string, file: File): Promise<void> {
    const response = await storageObject(bucket, path, {
        method: "POST",
        headers: {
            "cache-control": "31536000",
            "content-type": file.type,
            "x-upsert": "false",
        },
        body: file,
    });
    if (!response.ok) {
        throw await storageError(response);
    }
}

export async function downloadStorageImage(bucket: string, path: string): Promise<Response> {
    const response = await storageObject(bucket, path, { method: "GET" });
    if (response.status === 404) {
        throw new HttpError(404, "form image not found");
    }
    if (!response.ok) {
        throw await storageError(response);
    }
    return response;
}

export async function deleteStorageImageBestEffort(bucket: string, path: string): Promise<void> {
    try {
        const response = await storageObject(bucket, path, { method: "DELETE" });
        if (!response.ok && response.status !== 404) {
            console.warn(`Unable to remove Forms media object (${response.status})`);
        }
    } catch (error) {
        console.warn("Unable to remove Forms media object", error);
    }
}

async function storageObject(bucket: string, path: string, init: RequestInit): Promise<Response> {
    const key = serviceRoleKey();
    const headers = new Headers(init.headers);
    headers.set("apikey", key);
    if (key.startsWith("sb_")) {
        headers.delete("authorization");
    } else {
        headers.set("authorization", `Bearer ${key}`);
    }
    const bucketPath = encodeURIComponent(bucket);
    const objectPath = path.split("/").map(encodeURIComponent).join("/");
    return await fetch(`${supabaseUrl()}/storage/v1/object/${bucketPath}/${objectPath}`, { ...init, headers });
}

async function storageError(response: Response): Promise<HttpError> {
    const body = await response.json().catch(() => null);
    const message =
        isRecord(body) && typeof body.message === "string"
            ? body.message
            : `Supabase Storage request failed (${response.status})`;
    return new HttpError(502, message);
}

import { requireCmsAdmin } from "../auth.ts";
import { boundedInteger, HttpError, isRecord, json, queryText, requestBody } from "../http.ts";
import { rpcRecord } from "../rest.ts";

export async function handleSubmissionRoute(route: string, request: Request): Promise<Response | null> {
    if (!route.startsWith("/admin/submission")) {
        return null;
    }
    const actor = requireCmsAdmin(request);
    const url = new URL(request.url);
    if (route === "/admin/submissions") {
        requireMethod(request, "GET");
        return json(
            await rpcRecord("list_submissions", {
                p_form_key: queryText(url, "key"),
                p_status: queryText(url, "status"),
                p_limit: boundedInteger(url.searchParams.get("limit"), "limit", 100, 1, 200),
                p_offset: boundedInteger(url.searchParams.get("offset"), "offset", 0, 0, 1000000),
            }),
        );
    }
    if (route === "/admin/submission") {
        requireMethod(request, "GET");
        return json(await submissionDetail(numericId(queryText(url, "id", true))));
    }
    if (route === "/admin/submission/status") {
        requireMethod(request, "POST");
        const body = await requestBody(request);
        const id = boundedInteger(body.id, "id", 0, 1, Number.MAX_SAFE_INTEGER);
        await rpcRecord("update_submission_status", {
            p_submission_id: id,
            p_status: body.status,
            p_actor_id: actor,
        });
        return json(await submissionDetail(id));
    }
    return null;
}

async function submissionDetail(id: number): Promise<Record<string, unknown>> {
    const submission = await rpcRecord("get_submission", { p_submission_id: id });
    const rawAnswers = isRecord(submission.answers) ? submission.answers : {};
    const definition = isRecord(submission.definition) ? submission.definition : {};
    const rows: Record<string, unknown>[] = [];
    for (const section of Array.isArray(definition.steps) ? definition.steps : []) {
        if (!isRecord(section) || !Array.isArray(section.fields)) {
            continue;
        }
        for (const field of section.fields) {
            if (!isRecord(field) || typeof field.key !== "string") {
                continue;
            }
            rows.push({
                key: field.key,
                section: String(section.title ?? "Section"),
                question: String(field.label ?? field.key),
                answer: displayAnswer(rawAnswers[field.key], field),
            });
        }
    }
    const { definition: _definition, answers: _answers, ...detail } = submission;
    return { ...detail, answers: rows };
}

function displayAnswer(value: unknown, field: Record<string, unknown>): string {
    if (value === undefined || value === null || value === "") {
        return "—";
    }
    if (field.type === "checkbox") {
        return String(value) === "true" ? "Yes" : "No";
    }
    const labels = new Map(
        (Array.isArray(field.options) ? field.options : [])
            .filter(isRecord)
            .map((option) => [
                String(option.key ?? option.value ?? ""),
                String(option.label ?? option.key ?? option.value ?? ""),
            ]),
    );
    const displayed = (Array.isArray(value) ? value : [value]).map((item) => labels.get(String(item)) ?? String(item));
    return displayed.join(", ");
}

function numericId(value: string): number {
    return boundedInteger(value, "id", 0, 1, Number.MAX_SAFE_INTEGER);
}

function requireMethod(request: Request, method: string): void {
    if (request.method !== method) {
        throw new HttpError(405, `method must be ${method}`);
    }
}

import { boundedInteger, json, methodNotAllowed, requestBody } from "../http.ts";
import { rpcRecord } from "../rest.ts";

export async function handleSystemRoute(route: string, request: Request): Promise<Response | null> {
    if (route === "/system/health") {
        if (request.method !== "GET") {
            return methodNotAllowed("GET");
        }
        await rpcRecord("list_managed_forms", { p_limit: 1, p_offset: 0 });
        return json({ ok: true });
    }
    if (route === "/system/retention") {
        if (request.method !== "POST") {
            return methodNotAllowed("POST");
        }
        const body = await requestBody(request);
        return json(
            await rpcRecord("purge_expired_submissions", {
                p_retention_days: boundedInteger(body.retentionDays, "retentionDays", 0, 1, 3650),
                p_batch_size: boundedInteger(body.batchSize, "batchSize", 500, 1, 2000),
            }),
        );
    }
    return null;
}

import { cmsUserId } from "../auth.ts";
import { boundedInteger, HttpError, json, methodNotAllowed, queryText, requestBody } from "../http.ts";
import { rpcRecord } from "../rest.ts";
import { formDefinition, submissionAnswers } from "../validation.ts";

export async function handleVisitorRoute(route: string, request: Request): Promise<Response | null> {
    const authenticated = route.startsWith("/authenticated/");
    if (!authenticated && !route.startsWith("/public/")) {
        return null;
    }
    const actor = authenticated ? cmsUserId(request) : null;
    if (route.endsWith("/form")) {
        if (request.method !== "GET") {
            return methodNotAllowed("GET");
        }
        return json(await publishedForm(request, actor));
    }
    if (route.endsWith("/submission")) {
        if (request.method !== "POST") {
            return methodNotAllowed("POST");
        }
        return await submit(request, actor);
    }
    return null;
}

async function publishedForm(request: Request, actor: string | null): Promise<Record<string, unknown>> {
    const url = new URL(request.url);
    return await rpcRecord("get_published_form", {
        p_form_key: queryText(url, "key", true),
        p_version: url.searchParams.has("version")
            ? boundedInteger(url.searchParams.get("version"), "version", 1, 1, 2147483647)
            : null,
        p_actor_id: actor,
    });
}

async function submit(request: Request, actor: string | null): Promise<Response> {
    const body = await requestBody(request);
    const published = await publishedForm(request, actor);
    const definition = formDefinition(published.definition);
    const website = typeof body.website === "string" ? body.website.trim() : "";
    if (website || completedTooQuickly(body.startedAt, definition.minCompletionMs)) {
        return json({ ok: true, receiptId: crypto.randomUUID() }, 202);
    }
    const idempotencyKey = identifier(body.idempotencyKey, "idempotencyKey", 16, 200);
    const sessionId = identifier(body.sessionId, "sessionId", 36, 36);
    const version = boundedInteger(body.version, "version", 0, 1, 2147483647);
    if (version !== published.version) {
        throw new HttpError(409, "the form version changed; reload before submitting");
    }
    const result = await rpcRecord("submit_form", {
        p_form_key: published.key,
        p_version: version,
        p_idempotency_key: idempotencyKey,
        p_session_id: sessionId,
        p_answers: submissionAnswers(definition, body.answers),
        p_actor_id: actor,
        p_metadata: { locale: request.headers.get("accept-language")?.slice(0, 64) || null },
    });
    return json(result, 202);
}

function identifier(value: unknown, name: string, minimum: number, maximum: number): string {
    if (
        typeof value !== "string" ||
        value.length < minimum ||
        value.length > maximum ||
        !/^[A-Za-z0-9_-]+$/.test(value)
    ) {
        throw new HttpError(422, `${name} is invalid`);
    }
    return value;
}

function completedTooQuickly(startedAt: unknown, minimum: unknown): boolean {
    const timestamp = typeof startedAt === "string" ? Date.parse(startedAt) : Number.NaN;
    const threshold = Number.isFinite(Number(minimum)) ? Math.min(Math.max(Number(minimum), 0), 60000) : 1000;
    if (!Number.isFinite(timestamp)) {
        throw new HttpError(422, "startedAt is invalid");
    }
    return Date.now() - timestamp < threshold;
}

import { HttpError, isRecord } from "./http.ts";

const fieldTypes = new Set(["text", "email", "tel", "number", "date", "textarea", "select", "choice", "checkbox"]);

export function formDefinition(value: unknown): Record<string, unknown> {
    if (typeof value === "string") {
        value = parseJson(value);
    }
    if (!isRecord(value) || value.schemaVersion !== 1 || typeof value.title !== "string") {
        throw new HttpError(422, "definition must use schemaVersion 1 and include a title");
    }
    const steps = value.steps;
    if (!Array.isArray(steps) || steps.length < 1 || steps.length > 20) {
        throw new HttpError(422, "definition must contain between 1 and 20 steps");
    }
    const keys = new Set<string>();
    const stepIds = new Set<string>();
    let fieldCount = 0;
    for (const step of steps) {
        if (!isRecord(step) || !shortText(step.id, 80) || !shortText(step.title, 240) || !Array.isArray(step.fields)) {
            throw new HttpError(422, "each step needs a stable id, title, and fields array");
        }
        if (stepIds.has(step.id as string)) {
            throw new HttpError(422, "step ids must be unique");
        }
        stepIds.add(step.id as string);
        for (const field of step.fields) {
            validateField(field, keys);
            fieldCount += 1;
        }
    }
    if (fieldCount < 1 || fieldCount > 100 || JSON.stringify(value).length > 262144) {
        throw new HttpError(422, "definition is too large");
    }
    return value;
}

export function submissionAnswers(definition: Record<string, unknown>, value: unknown): Record<string, unknown> {
    if (!isRecord(value) || JSON.stringify(value).length > 1048576) {
        throw new HttpError(422, "answers must be an object smaller than 1 MB");
    }
    const fields = definitionFields(definition);
    const errors: Record<string, string> = {};
    for (const key of Object.keys(value)) {
        if (!fields.has(key)) {
            errors[key] = "Unknown field";
        }
    }
    for (const [key, field] of fields) {
        const answer = value[key];
        if (field.required === true && emptyAnswer(answer)) {
            errors[key] = "This field is required";
            continue;
        }
        if (answer !== undefined) {
            validateAnswer(key, field, answer, errors);
        }
    }
    if (Object.keys(errors).length > 0) {
        throw new HttpError(422, "some answers are invalid", errors);
    }
    return value;
}

function validateField(value: unknown, keys: Set<string>): void {
    if (!isRecord(value) || !shortText(value.key, 80) || !/^[a-z][A-Za-z0-9_]*$/.test(value.key as string)) {
        throw new HttpError(422, "each field needs a valid stable key");
    }
    if (keys.has(value.key as string) || !shortText(value.label, 240) || !fieldTypes.has(String(value.type))) {
        throw new HttpError(422, "field keys must be unique and every field needs a supported type and label");
    }
    keys.add(value.key as string);
    if (["select", "choice"].includes(String(value.type))) {
        if (!Array.isArray(value.options) || value.options.length < 1 || value.options.length > 50) {
            throw new HttpError(422, `${value.key} needs between 1 and 50 options`);
        }
        const optionKeys = new Set<string>();
        for (const option of value.options) {
            const key = isRecord(option) ? stableOptionKey(option) : "";
            if (!isRecord(option) || !shortText(option.label, 160) || !key) {
                throw new HttpError(422, `${value.key} contains an invalid option`);
            }
            if (optionKeys.has(key)) {
                throw new HttpError(422, `${value.key} contains duplicate option keys`);
            }
            optionKeys.add(key);
            if (value.presentation === "image-grid" && !validImage(option)) {
                throw new HttpError(422, `${value.key} image choices need a Forms image`);
            }
        }
    }
    if (value.presentation !== undefined && (value.type !== "choice" || value.presentation !== "image-grid")) {
        throw new HttpError(422, `${value.key} contains an invalid choice presentation`);
    }
}

function definitionFields(definition: Record<string, unknown>): Map<string, Record<string, unknown>> {
    const fields = new Map<string, Record<string, unknown>>();
    for (const step of definition.steps as Record<string, unknown>[]) {
        for (const field of step.fields as Record<string, unknown>[]) {
            fields.set(field.key as string, field);
        }
    }
    return fields;
}

function validateAnswer(
    key: string,
    field: Record<string, unknown>,
    answer: unknown,
    errors: Record<string, string>,
): void {
    const values = Array.isArray(answer) ? answer : [answer];
    if (values.length > 50 || values.some((item) => typeof item !== "string" || item.length > 10000)) {
        errors[key] = "Invalid answer";
        return;
    }
    const options = Array.isArray(field.options) ? new Set(field.options.filter(isRecord).map(stableOptionKey)) : null;
    if (options && values.some((item) => !options.has(item as string))) {
        errors[key] = "Choose one of the available options";
    }
    if (field.multiple !== true && Array.isArray(answer)) {
        errors[key] = "Choose a single value";
    }
    if (field.type === "checkbox" && values.some((item) => !["true", "false"].includes(String(item)))) {
        errors[key] = "Invalid checkbox value";
    }
    const first = String(values[0] ?? "");
    if (field.type === "email" && first && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(first)) {
        errors[key] = "Enter a valid email address";
    }
    if (field.type === "number" && first && !Number.isFinite(Number(first))) {
        errors[key] = "Enter a valid number";
    }
    if (field.type === "date" && first && !/^\d{4}-\d{2}-\d{2}$/.test(first)) {
        errors[key] = "Enter a valid date";
    }
}

function emptyAnswer(value: unknown): boolean {
    return (
        value === undefined ||
        value === null ||
        value === "" ||
        value === "false" ||
        (Array.isArray(value) && value.length === 0)
    );
}

function shortText(value: unknown, maximum: number): boolean {
    return typeof value === "string" && value.trim().length > 0 && value.length <= maximum;
}

function stableOptionKey(option: Record<string, unknown>): string {
    const key = String(option.key ?? option.value ?? "").trim();
    return /^[a-z][A-Za-z0-9_-]*$/.test(key) && key.length <= 80 ? key : "";
}

function validImageUrl(value: unknown): boolean {
    if (typeof value !== "string" || !value || value.length > 2048) {
        return false;
    }
    if (value.startsWith("/") && !value.startsWith("//")) {
        return true;
    }
    try {
        return new URL(value).protocol === "https:";
    } catch {
        return false;
    }
}

function validImage(option: Record<string, unknown>): boolean {
    if (isRecord(option.image)) {
        const mediaId = option.image.mediaId;
        if (typeof mediaId === "string" && /^[1-9][0-9]{0,18}$/.test(mediaId)) {
            return (
                option.image.alt === undefined ||
                (typeof option.image.alt === "string" && option.image.alt.length <= 240)
            );
        }
    }
    return validImageUrl(option.imageUrl);
}

function parseJson(value: string): unknown {
    try {
        return JSON.parse(value);
    } catch {
        throw new HttpError(422, "definitionJson must contain valid JSON");
    }
}

