create or replace function forms.save_form_draft(
    p_form_key text,
    p_title text,
    p_description text,
    p_access_mode text,
    p_definition jsonb,
    p_actor_id text default null
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
    saved_form_id bigint;
begin
    if jsonb_typeof(p_definition) <> 'object' then
        raise exception 'validation: definition must be an object';
    end if;
    insert into forms.forms (
        form_key, title, description, access_mode, draft_definition, created_by, updated_by
    ) values (
        p_form_key, btrim(p_title), nullif(btrim(p_description), ''), p_access_mode, p_definition, p_actor_id, p_actor_id
    )
    on conflict (form_key) do update set
        title = excluded.title,
        description = excluded.description,
        access_mode = excluded.access_mode,
        draft_definition = excluded.draft_definition,
        lifecycle_status = 'active',
        updated_by = excluded.updated_by
    returning id into saved_form_id;
    perform forms.sync_draft_media(saved_form_id, p_definition);
    return forms.get_managed_form(p_form_key);
end;
$$;

create or replace function forms.publish_form(p_form_key text, p_actor_id text default null)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
    locked_form forms.forms%rowtype;
    next_version integer;
begin
    select * into locked_form
    from forms.forms
    where form_key = p_form_key
    for update;
    if not found then
        raise exception 'not_found: form does not exist';
    end if;
    next_version := coalesce(locked_form.published_version, 0) + 1;
    insert into forms.form_versions (
        form_id, version_number, definition_schema_version, title, description,
        access_mode, definition, published_by
    ) values (
        locked_form.id,
        next_version,
        (locked_form.draft_definition ->> 'schemaVersion')::integer,
        locked_form.title,
        locked_form.description,
        locked_form.access_mode,
        locked_form.draft_definition,
        p_actor_id
    );
    insert into forms.form_version_media (form_id, version_number, media_id)
    select locked_form.id, next_version, media_id
    from forms.form_draft_media
    where form_id = locked_form.id;
    update forms.forms set
        published_version = next_version,
        lifecycle_status = 'active',
        updated_by = p_actor_id
    where id = locked_form.id;
    return forms.get_managed_form(p_form_key);
exception
    when invalid_text_representation then
        raise exception 'validation: definition schemaVersion must be an integer';
end;
$$;

create or replace function forms.archive_form(p_form_key text, p_actor_id text default null)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
begin
    update forms.forms set lifecycle_status = 'archived', updated_by = p_actor_id
    where form_key = p_form_key;
    if not found then
        raise exception 'not_found: form does not exist';
    end if;
    return forms.get_managed_form(p_form_key);
end;
$$;

create or replace function forms.definition_media_ids(p_definition jsonb)
returns setof bigint
language plpgsql
stable
set search_path = ''
as $$
declare
    value jsonb;
    media_id text;
begin
    for value in
        select match
        from jsonb_path_query(p_definition, '$.steps[*].fields[*].options[*].image.mediaId') as matches(match)
    loop
        media_id := case when jsonb_typeof(value) = 'string' then value #>> '{}' else null end;
        if media_id is null or media_id !~ '^[1-9][0-9]{0,18}$' then
            raise exception 'validation: form media references must be positive identifiers';
        end if;
        return next media_id::bigint;
    end loop;
exception
    when numeric_value_out_of_range then
        raise exception 'validation: form media reference is too large';
end;
$$;

create or replace function forms.sync_draft_media(p_form_id bigint, p_definition jsonb)
returns void
language plpgsql
security invoker
set search_path = ''
as $$
begin
    if exists (
        select 1
        from forms.definition_media_ids(p_definition) referenced(media_id)
        left join forms.media stored on stored.form_id = p_form_id and stored.id = referenced.media_id
        where stored.id is null
    ) then
        raise exception 'validation: a form image does not belong to this form';
    end if;

    delete from forms.form_draft_media link
    where link.form_id = p_form_id
      and not exists (
          select 1 from forms.definition_media_ids(p_definition) referenced(media_id)
          where referenced.media_id = link.media_id
      );

    insert into forms.form_draft_media (form_id, media_id)
    select distinct p_form_id, referenced.media_id
    from forms.definition_media_ids(p_definition) referenced(media_id)
    on conflict (form_id, media_id) do nothing;
end;
$$;

create or replace function forms.create_media(
    p_form_key text,
    p_storage_bucket text,
    p_storage_path text,
    p_mime_type text,
    p_file_size bigint,
    p_width integer,
    p_height integer,
    p_original_filename text,
    p_actor_id text default null
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
    owner forms.forms%rowtype;
    stored forms.media%rowtype;
begin
    select * into owner from forms.forms where form_key = p_form_key;
    if not found then
        raise exception 'not_found: form does not exist';
    end if;
    insert into forms.media (
        form_id, storage_bucket, storage_path, mime_type, file_size,
        width, height, original_filename, created_by
    ) values (
        owner.id, p_storage_bucket, p_storage_path, lower(p_mime_type), p_file_size,
        p_width, p_height, btrim(p_original_filename), p_actor_id
    ) returning * into stored;
    return jsonb_build_object(
        'mediaId', stored.id,
        'mimeType', stored.mime_type,
        'fileSize', stored.file_size,
        'width', stored.width,
        'height', stored.height,
        'originalFilename', stored.original_filename
    );
end;
$$;

create or replace function forms.get_managed_media_context(p_media_id bigint)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
    result jsonb;
begin
    select jsonb_build_object(
        'mediaId', media.id,
        'formKey', owner.form_key,
        'storageBucket', media.storage_bucket,
        'storagePath', media.storage_path,
        'mimeType', media.mime_type
    ) into result
    from forms.media media
    join forms.forms owner on owner.id = media.form_id
    where media.id = p_media_id;
    if result is null then
        raise exception 'not_found: form image does not exist';
    end if;
    return result;
end;
$$;

create or replace function forms.get_published_media_context(
    p_form_key text,
    p_version integer,
    p_media_id bigint,
    p_actor_id text default null
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
    result jsonb;
    required_access text;
begin
    select jsonb_build_object(
        'mediaId', media.id,
        'storageBucket', media.storage_bucket,
        'storagePath', media.storage_path,
        'mimeType', media.mime_type
    ), version.access_mode
    into result, required_access
    from forms.forms owner
    join forms.form_versions version
      on version.form_id = owner.id and version.version_number = p_version
    join forms.form_version_media link
      on link.form_id = version.form_id and link.version_number = version.version_number
    join forms.media media on media.id = link.media_id and media.form_id = owner.id
    where owner.form_key = p_form_key
      and owner.lifecycle_status = 'active'
      and media.id = p_media_id;
    if result is null or (required_access = 'authenticated' and nullif(btrim(p_actor_id), '') is null) then
        raise exception 'not_found: form image is not available';
    end if;
    return result;
end;
$$;

create or replace function forms.purge_expired_submissions(
    p_retention_days integer,
    p_batch_size integer default 500
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
    deleted_count integer;
begin
    if p_retention_days < 1 or p_retention_days > 3650 then
        raise exception 'validation: retentionDays must be between 1 and 3650';
    end if;
    with candidates as (
        select id
        from forms.submissions
        where created_at < now() - make_interval(days => p_retention_days)
        order by created_at, id
        for update skip locked
        limit least(greatest(coalesce(p_batch_size, 500), 1), 2000)
    ), deleted as (
        delete from forms.submissions s
        using candidates c
        where s.id = c.id
        returning s.id
    )
    select count(*) into deleted_count from deleted;
    return jsonb_build_object('ok', true, 'deleted', deleted_count);
end;
$$;

create or replace function forms.submit_form(
    p_form_key text,
    p_version integer,
    p_idempotency_key text,
    p_session_id uuid,
    p_answers jsonb,
    p_actor_id text default null,
    p_metadata jsonb default '{}'::jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
    target_form forms.forms%rowtype;
    version_access text;
    submission_row forms.submissions%rowtype;
begin
    select f.* into target_form
    from forms.forms f
    where f.form_key = p_form_key and f.lifecycle_status = 'active'
    for share;
    if not found then
        raise exception 'not_found: form is not available';
    end if;
    select v.access_mode into version_access
    from forms.form_versions v
    where v.form_id = target_form.id and v.version_number = p_version;
    if not found then
        raise exception 'not_found: form version is not available';
    end if;
    if version_access = 'authenticated' and nullif(btrim(p_actor_id), '') is null then
        raise exception 'not_found: form is not available';
    end if;

    insert into forms.submissions (
        form_id, form_version, idempotency_key, session_id, answers, submitted_by, metadata
    ) values (
        target_form.id, p_version, p_idempotency_key, p_session_id, p_answers, p_actor_id, p_metadata
    )
    on conflict (form_id, idempotency_key) do nothing
    returning * into submission_row;

    if submission_row.id is null then
        select * into submission_row
        from forms.submissions
        where form_id = target_form.id and idempotency_key = p_idempotency_key;
        if submission_row.answers <> p_answers
           or submission_row.form_version <> p_version
           or submission_row.session_id <> p_session_id then
            raise exception 'conflict: idempotency key was already used with different answers';
        end if;
    end if;
    return jsonb_build_object('ok', true, 'receiptId', submission_row.receipt_id);
end;
$$;

create or replace function forms.update_submission_status(
    p_submission_id bigint,
    p_status text,
    p_actor_id text default null
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
    result jsonb;
begin
    update forms.submissions s set status = p_status, updated_by = p_actor_id
    from forms.forms f
    where s.id = p_submission_id and f.id = s.form_id
    returning jsonb_build_object(
        'id', s.id,
        'receiptId', s.receipt_id,
        'formKey', f.form_key,
        'formVersion', s.form_version,
        'status', s.status,
        'answers', s.answers,
        'submittedBy', s.submitted_by,
        'createdAt', s.created_at,
        'updatedAt', s.updated_at
    ) into result;
    if result is null then
        raise exception 'not_found: submission does not exist';
    end if;
    return result;
end;
$$;

