                                "id"
                            ],
                            "deferrable": false,
                            "initiallyDeferred": false,
                            "validated": true
                        }
                    ]
                },
                {
                    "name": "submissions",
                    "kind": "table",
                    "columns": [
                        {
                            "name": "answers",
                            "type": "jsonb",
                            "nullable": false
                        },
                        {
                            "name": "created_at",
                            "type": "timestamptz",
                            "nullable": false,
                            "default": "now()"
                        },
                        {
                            "name": "form_id",
                            "type": "bigint",
                            "nullable": false
                        },
                        {
                            "name": "form_version",
                            "type": "integer",
                            "nullable": false
                        },
                        {
                            "name": "id",
                            "type": "bigint",
                            "nullable": false,
                            "identity": "always",
                            "sequenceDependency": "internal"
                        },
                        {
                            "name": "idempotency_key",
                            "type": "text",
                            "nullable": false
                        },
                        {
                            "name": "metadata",
                            "type": "jsonb",
                            "nullable": false,
                            "default": "'{}'::jsonb"
                        },
                        {
                            "name": "receipt_id",
                            "type": "uuid",
                            "nullable": false,
                            "default": "gen_random_uuid()"
                        },
                        {
                            "name": "session_id",
                            "type": "uuid",
                            "nullable": false
                        },
                        {
                            "name": "status",
                            "type": "text",
                            "nullable": false,
                            "default": "'received'::text"
                        },
                        {
                            "name": "submitted_by",
                            "type": "text",
                            "nullable": true
                        },
                        {
                            "name": "updated_at",
                            "type": "timestamptz",
                            "nullable": false,
                            "default": "now()"
                        },
                        {
                            "name": "updated_by",
                            "type": "text",
                            "nullable": true
                        }
                    ],
                    "constraints": [
                        {
                            "kind": "check",
                            "name": "submissions_actor_length",
                            "expression": "(((submitted_by IS NULL) OR (length(submitted_by) <= 200)) AND ((updated_by IS NULL) OR (length(updated_by) <= 200)))",
                            "deferrable": false,
                            "initiallyDeferred": false,
                            "validated": true
                        },
                        {
                            "kind": "check",
                            "name": "submissions_answers_object",
                            "expression": "(jsonb_typeof(answers) = 'object'::text)",
                            "deferrable": false,
                            "initiallyDeferred": false,
                            "validated": true
                        },
                        {
                            "kind": "check",
                            "name": "submissions_answers_size",
                            "expression": "(pg_column_size(answers) <= 1048576)",
                            "deferrable": false,
                            "initiallyDeferred": false,
                            "validated": true
                        },
                        {
                            "kind": "foreign-key",
                            "name": "submissions_form_version_fk",
                            "columns": [
                                "form_id",
                                "form_version"
                            ],
                            "references": {
                                "namespace": "forms",
                                "relation": "form_versions",
                                "columns": [
                                    "form_id",
                                    "version_number"
                                ]
                            },
                            "onUpdate": "no-action",
                            "onDelete": "restrict",
                            "matchType": "simple",
                            "deferrable": false,
                            "initiallyDeferred": false,
                            "validated": true
                        },
                        {
                            "kind": "check",
                            "name": "submissions_form_version_valid",
                            "expression": "(form_version > 0)",
                            "deferrable": false,
                            "initiallyDeferred": false,
                            "validated": true
                        },
                        {
                            "kind": "check",
                            "name": "submissions_idempotency_length",
                            "expression": "((length(idempotency_key) >= 16) AND (length(idempotency_key) <= 200))",
                            "deferrable": false,
                            "initiallyDeferred": false,
                            "validated": true
                        },
                        {
                            "kind": "unique",
                            "name": "submissions_idempotency_unique",
                            "columns": [
                                "form_id",
                                "idempotency_key"
                            ],
                            "nullsNotDistinct": false,
                            "deferrable": false,
                            "initiallyDeferred": false,
                            "validated": true
                        },
                        {
                            "kind": "check",
                            "name": "submissions_metadata_object",
                            "expression": "(jsonb_typeof(metadata) = 'object'::text)",
                            "deferrable": false,
                            "initiallyDeferred": false,
                            "validated": true
                        },
                        {
                            "kind": "check",
                            "name": "submissions_metadata_size",
                            "expression": "(pg_column_size(metadata) <= 16384)",
                            "deferrable": false,
                            "initiallyDeferred": false,
                            "validated": true
                        },
                        {
                            "kind": "primary-key",
                            "name": "submissions_pkey",
                            "columns": [
                                "id"
                            ],
                            "deferrable": false,
                            "initiallyDeferred": false,
                            "validated": true
                        },
                        {
                            "kind": "unique",
                            "name": "submissions_receipt_id_unique",
                            "columns": [
                                "receipt_id"
                            ],
                            "nullsNotDistinct": false,
                            "deferrable": false,
                            "initiallyDeferred": false,
                            "validated": true
                        },
                        {
                            "kind": "check",
                            "name": "submissions_status_valid",
                            "expression": "(status = ANY (ARRAY['received'::text, 'reviewed'::text, 'archived'::text]))",
                            "deferrable": false,
                            "initiallyDeferred": false,
                            "validated": true
                        }
                    ]
                }
            ]
        }
    ]
}

definitions/configuration/theme.json.content:
{
    "categories": [
        {
            "id": "form-surface",
            "label": "Form surface",
            "description": "Colours shared by the renderer, fields, progress, and completion state.",
            "tokens": [
                {
                    "id": "accent",
                    "label": "Accent",
                    "type": "color",
                    "defaults": {
                        "light": "var(--primary-base, #b9583f)"
                    }
                },
                {
                    "id": "background",
                    "label": "Background",
                    "type": "color",
                    "defaults": {
                        "light": "var(--bg-surface, #fffdf9)"
                    }
                },
                {
                    "id": "text",
                    "label": "Text",
                    "type": "color",
                    "defaults": {
                        "light": "var(--text-main, #292724)"
                    }
                },
                {
                    "id": "muted-text",
                    "label": "Muted text",
                    "type": "color",
                    "defaults": {
                        "light": "var(--text-muted, #77716b)"
                    }
                },
                {
                    "id": "border",
                    "label": "Border",
                    "type": "color",
                    "defaults": {
                        "light": "var(--border-default, #dfd8ce)"
                    }
                }
            ]
        }
    ]
}

definitions/root.json.content:
{
    "schema": "cms.integration.definition.v1",
    "kind": "forms",
    "label": "Forms",
    "version": "2.0.0",
    "category": "Content",
    "description": "Build versioned multi-step forms, publish them through CMS Sources, and review their submissions.",
    "icon": {
        "path": "assets/icon.svg"
    },
    "inputs": {
        "$include": "configuration/inputs.json"
    },
    "dependencies": {
        "$include": "configuration/dependencies.json"
    },
    "ui": {
        "$include": "configuration/ui.json"
    },
    "theme": {
        "$include": "configuration/theme.json"
    },
    "generatedSecrets": {
        "$include": "configuration/generated-secrets.json"
    },
    "connectors": {
        "$include": "configuration/connectors.json"
    },
    "afterInstallation": {
        "$include": "configuration/after-installation.json"
    },
    "artifacts": {
        "$files": [
            "artifacts/sources/primary/definition.json",
            "artifacts/blocs/form-renderer.json",
            "artifacts/dashboards/forms.json",
            "artifacts/dashboards/submissions.json"
        ]
    }
}
